#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const int MAX_ARGS = 65;   // maximum number of arguments (excluding program name)
    const int MAX_LEN  = 1024; // maximum allowed length of each argument

    // Too many arguments (excluding program name)
    if (argc - 1 > MAX_ARGS) {
        puts("TOO_MANY");
        return 0;
    }

    // No arguments provided (other than program name)
    if (argc <= 1) {
        puts("EMPTY");
        return 0;
    }

    // Validate length of each argument
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > MAX_LEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    // Compute longest common prefix among all arguments
    const char *ref = argv[1];
    size_t prefix_len = strlen(ref);

    for (int i = 2; i < argc; ++i) {
        const char *s = argv[i];
        size_t j = 0;
        while (j < prefix_len && ref[j] && s[j] && ref[j] == s[j]) {
            ++j;
        }
        prefix_len = j;
        if (prefix_len == 0) {
            break;
        }
    }

    if (prefix_len == 0) {
        puts("EMPTY");
        return 0;
    }

    // Output the prefix followed by a newline
    fwrite(ref, 1, prefix_len, stdout);
    putchar('\n');
    return 0;
}
